// Generates app/data/tasbeehPresets.generated.ts from the LEGACY Tasbeeh composable's `tasbeehPresets` (id, Arabic, transliteration, meaning).
//
//   node scripts/gen-tasbeeh-presets.mjs
//
// The legacy list sits inside a Nuxt composable that cannot be imported cleanly, so it is read through scripts/lib/legacy-tasbeeh.mjs. The
// legacy colour name (a Vuetify colour) is not carried over. Never hand-edit the generated file; re-run this script. tests/tasbeeh.test.ts
// regenerates the list in memory and compares it with the file.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadLegacyTasbeeh } from "./lib/legacy-tasbeeh.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const legacy = await loadLegacyTasbeeh({ get: (_k, d) => d, set: () => {} });
const presets = legacy.tasbeehPresets.map((p) => ({ id: p.id, arabic: p.arabic, transliteration: p.transliteration, meaning: p.meaning }));
if (presets.length < 1 || presets.some((p) => typeof p.id !== "string" || !p.id || typeof p.transliteration !== "string")) throw new Error("tasbeeh presets: unexpected shape");

const body = `// GENERATED by scripts/gen-tasbeeh-presets.mjs from the legacy app/composables/useTasbeeh.ts. Do not edit by hand; re-run the script.
// The legacy dhikr presets (the generated-data folder is the one place Arabic may live). The legacy colour name is not carried over.
export interface TasbeehPreset {
  id: string;
  arabic: string;
  transliteration: string;
  meaning: string;
}
export const TASBEEH_PRESETS: TasbeehPreset[] = ${JSON.stringify(presets, null, 2)};
`;
const out = path.resolve(here, "../app/data/tasbeehPresets.generated.ts");
fs.writeFileSync(out, body);
console.log(`wrote ${out}: ${presets.length} presets`);
